fn to_sdk_attribute_value(v: &Union10<AttributeValueS, AttributeValueN, AttributeValueB, AttributeValueSs, AttributeValueNs, AttributeValueBs, AttributeValueM, AttributeValueL, AttributeValueBool, AttributeValueNull>) -> aws_sdk_dynamodb::types::AttributeValue {
    match v {
        Union10::U1(x) => aws_sdk_dynamodb::types::AttributeValue::S(x.value.clone()),
        Union10::U2(x) => aws_sdk_dynamodb::types::AttributeValue::N(x.value.clone()),
        Union10::U3(x) => aws_sdk_dynamodb::types::AttributeValue::B(aws_sdk_dynamodb::primitives::Blob::new(x.value.clone())),
        Union10::U4(x) => aws_sdk_dynamodb::types::AttributeValue::Ss(x.value.clone()),
        Union10::U5(x) => aws_sdk_dynamodb::types::AttributeValue::Ns(x.value.clone()),
        Union10::U6(x) => aws_sdk_dynamodb::types::AttributeValue::Bs(x.value.iter().map(|b| aws_sdk_dynamodb::primitives::Blob::new(b.clone())).collect()),
        Union10::U7(x) => aws_sdk_dynamodb::types::AttributeValue::M(x.value.iter().map(|(k, e)| (k.clone(), to_sdk_attribute_value(e))).collect()),
        Union10::U8(x) => aws_sdk_dynamodb::types::AttributeValue::L(x.value.iter().map(|e| to_sdk_attribute_value(e)).collect()),
        Union10::U9(x) => aws_sdk_dynamodb::types::AttributeValue::Bool(x.value),
        Union10::U10(x) => aws_sdk_dynamodb::types::AttributeValue::Null(x.value),
    }
}

fn from_sdk_attribute_value(v: &aws_sdk_dynamodb::types::AttributeValue) -> Union10<AttributeValueS, AttributeValueN, AttributeValueB, AttributeValueSs, AttributeValueNs, AttributeValueBs, AttributeValueM, AttributeValueL, AttributeValueBool, AttributeValueNull> {
    match v {
        aws_sdk_dynamodb::types::AttributeValue::S(x) => Union10::U1(AttributeValueS { value: x.to_string() }),
        aws_sdk_dynamodb::types::AttributeValue::N(x) => Union10::U2(AttributeValueN { value: x.to_string() }),
        aws_sdk_dynamodb::types::AttributeValue::B(x) => Union10::U3(AttributeValueB { value: x.as_ref().to_vec() }),
        aws_sdk_dynamodb::types::AttributeValue::Ss(x) => Union10::U4(AttributeValueSs { value: x.iter().map(|s| s.to_string()).collect() }),
        aws_sdk_dynamodb::types::AttributeValue::Ns(x) => Union10::U5(AttributeValueNs { value: x.iter().map(|s| s.to_string()).collect() }),
        aws_sdk_dynamodb::types::AttributeValue::Bs(x) => Union10::U6(AttributeValueBs { value: x.iter().map(|b| b.as_ref().to_vec()).collect() }),
        aws_sdk_dynamodb::types::AttributeValue::M(x) => Union10::U7(AttributeValueM { value: { let mut __es: Vec<_> = x.iter().map(|(k, e)| (k.clone(), from_sdk_attribute_value(e))).collect(); __es.sort_by(|a, b| a.0.cmp(&b.0)); crate::platform_std_core_map::canonical_map(__es) } }),
        aws_sdk_dynamodb::types::AttributeValue::L(x) => Union10::U8(AttributeValueL { value: x.iter().map(|e| from_sdk_attribute_value(e)).collect() }),
        aws_sdk_dynamodb::types::AttributeValue::Bool(x) => Union10::U9(AttributeValueBool { value: *x }),
        aws_sdk_dynamodb::types::AttributeValue::Null(x) => Union10::U10(AttributeValueNull { value: *x }),
        other => panic!("DynamoDB sent an attribute value this client does not map: {:?}", other),
    }
}

/// A code as the model names it: the shape id's name (`ns#Name`), and a legacy
/// `@awsQueryError` code mapped to the model's.
fn salvo_code(code: &str) -> String {
    let code = code.rsplit('#').next().unwrap_or(code);
    match code {
        "Throttling" => "ThrottlingException",
        other => other,
    }
    .to_string()
}

fn salvo_failure<E>(
    e: aws_sdk_dynamodb::error::SdkError<E, aws_sdk_dynamodb::config::http::HttpResponse>,
    extra: impl FnOnce(&E, &mut DdbError),
) -> Checked<Union2<DdbError, AwsError>>
where
    E: ProvideErrorMetadata + std::error::Error + Send + Sync + 'static,
{
    use aws_sdk_dynamodb::operation::RequestId;
    let text = format!("{}", aws_sdk_dynamodb::error::DisplayErrorContext(&e));
    let request_id = e.request_id().map(|r| r.to_string());
    let value = match &e {
        aws_sdk_dynamodb::error::SdkError::ServiceError(ctx) => {
            let err = ctx.err();
            let mut out = DdbError {
                code: salvo_code(err.code().unwrap_or("Unknown")),
                message: err.message().unwrap_or("").to_string(),
                status: ctx.raw().status().as_u16() as i32,
                request_id,
                item: None,
                throttling_reasons: None,
            };
            extra(err, &mut out);
            DdbFailure::ddb_error(out)
        }
        other => DdbFailure::aws_error(AwsError {
            code: match other {
                aws_sdk_dynamodb::error::SdkError::TimeoutError(_) => "TimeoutError",
                aws_sdk_dynamodb::error::SdkError::DispatchFailure(_) => "DispatchFailure",
                aws_sdk_dynamodb::error::SdkError::ResponseError(_) => "ResponseError",
                _ => "ConstructionFailure",
            }
            .to_string(),
            message: text,
        }),
    };
    Checked { value }
}

/// `~/` at the front of a path is the home directory, as a shell would read it.
fn salvo_expand_home(path: &str) -> String {
    match (path.strip_prefix("~/"), std::env::var("HOME")) {
        (Some(rest), Ok(home)) => format!("{home}/{rest}"),
        _ => path.to_string(),
    }
}

/// A Smithy timestamp as a `time.Instant`: nanoseconds since the epoch,
/// saturating outside `Instant`'s range (1678–2262).
fn salvo_instant(t: &aws_sdk_dynamodb::primitives::DateTime) -> crate::std_time::Instant {
    let nanos = t.as_nanos().clamp(i64::MIN as i128, i64::MAX as i128) as i64;
    crate::std_time::Instant { nanos }
}

/// A `time.Instant` as a Smithy timestamp.
fn salvo_date_time(at: &crate::std_time::Instant) -> aws_sdk_dynamodb::primitives::DateTime {
    aws_sdk_dynamodb::primitives::DateTime::from_nanos(at.nanos as i128).expect("an i64 of nanoseconds is a valid timestamp")
}
